// Minimal hand-written stub of the `express` package's public surface, enough
// for the TypeChecker to resolve `express.Express` / `express.Router` from a
// fixture without a heavy real install. See the tsindex README's "fixture
// stubs" note.
export interface Request {
  params: any;
  query: any;
}

export interface Response {
  send(body?: any): Response;
  json(body?: any): Response;
  status(code: number): Response;
}

export type Handler = (req: Request, res: Response, next?: () => void) => any;

export interface Router {
  get(path: string, ...handlers: Handler[]): Router;
  post(path: string, ...handlers: Handler[]): Router;
  put(path: string, ...handlers: Handler[]): Router;
  delete(path: string, ...handlers: Handler[]): Router;
  use(...handlers: any[]): Router;
}

export interface Express extends Router {
  listen(port: number, cb?: () => void): any;
}

declare function express(): Express;

declare namespace express {
  function Router(): Router;
}

export default express;
